Tool = Callable[..., Dict[str, Any]]

ZERO_WIDTH = re.compile(r"[\u200b-\u200f\u2060\ufeff]")
MULTISPACE = re.compile(r"\s+")
NUMBER_RE = re.compile(r"\b\d+(?:\.\d+)?\b")
MALAYALAM_RANGE = (0x0D00, 0x0D7F)

def _contains_malayalam(text: str) -> bool:
    return any(MALAYALAM_RANGE[0] <= ord(ch) <= MALAYALAM_RANGE[1] for ch in text)

def _normalize_text(text: Any) -> str:
    value = str(text or "")
    value = ZERO_WIDTH.sub("", value)
    value = value.replace("\r\n", "\n").replace("\r", "\n")
    return MULTISPACE.sub(" ", value).strip()

def _fold_text(text: Any) -> str:
    value = _normalize_text(text).lower()
    value = re.sub(r"[!?.,;:()[\]{}<>\"'`]+", " ", value)
    return MULTISPACE.sub(" ", value).strip()

def _tokens(text: str) -> List[str]:
    return re.findall(r"[a-z0-9\u0d00-\u0d7f][a-z0-9\u0d00-\u0d7f_-]*", _fold_text(text))

def _phrase_present(text: str, phrase: str) -> bool:
    return f" {_fold_text(phrase)} " in f" {_fold_text(text)} "

def _any_phrase(text: str, phrases: Iterable[str]) -> bool:
    return any(_phrase_present(text, p) for p in phrases)

@dataclass
class Signal:
    name: str
    score: float
    evidence: List[str] = field(default_factory=list)

@dataclass
class QueryProfile:
    raw: str
    normalized: str
    language: str
    intents: Dict[str, float]
    entities: Dict[str, List[str]]
    constraints: Dict[str, Any]
    flags: Dict[str, bool]
    signals: List[Signal] = field(default_factory=list)

@dataclass
class PlanStep:
    name: str
    priority: int
    reason: str
    optional: bool = False
    depends_on: List[str] = field(default_factory=list)

