class QueryAnalyzer:
    def detect_language(self, text: str) -> str:
        folded = _fold_text(text)
        ml = sum(_phrase_present(folded,x) for x in LANGUAGE_HINTS["malayalam"])
        en = sum(_phrase_present(folded,x) for x in LANGUAGE_HINTS["english"])
        mixed = sum(_phrase_present(folded,x) for x in LANGUAGE_HINTS["mixed"])
        if _contains_malayalam(text):
            return "mixed" if en or mixed else "malayalam"
        if mixed >= 2:
            return "mixed"
        if en >= ml:
            return "english"
        if ml:
            return "malayalam"
        return "unknown"

    def score_intents(self, text: str) -> Dict[str,float]:
        folded = _fold_text(text)
        scores = {}
        for intent, phrases in INTENT_GROUPS.items():
            score = 0.0
            for phrase in phrases:
                if _phrase_present(folded, phrase):
                    score += 1.0 + min(len(phrase)/25.0, 1.5)
            if score:
                scores[intent] = round(score,3)
        total = sum(scores.values()) or 1.0
        return {k: round(v/total,4) for k,v in scores.items()}

    def extract_actions(self, text: str) -> List[str]:
        folded = _fold_text(text)
        out=[]
        for name, phrases in ACTION_HINTS.items():
            hits=sum(_phrase_present(folded,p) for p in phrases)
            if hits:
                out.append((name,hits))
        return [x[0] for x in sorted(out,key=lambda x:(-x[1],x[0]))]

    def extract_preferences(self, text: str) -> List[str]:
        folded=_fold_text(text)
        return [name for name,phrases in PREFERENCE_HINTS.items()
                if any(_phrase_present(folded,p) for p in phrases)]

    def extract_budget(self,text:str)->Dict[str,Any]:
        folded=_fold_text(text)
        patterns=(
            r"(?:under|below|less than|within|budget of|around)\s*(?:rs\.?|₹)?\s*(\d+(?:\.\d+)?)\s*(k|thousand|lakh)?",
            r"(?:₹|rs\.?)\s*(\d+(?:\.\d+)?)\s*(k|thousand|lakh)?",
        )
        for pattern in patterns:
            m=re.search(pattern,folded,re.I)
            if m:
                amount=float(m.group(1)); suffix=(m.group(2) or "").lower()
                if suffix in ("k","thousand"): amount*=1000
                if suffix=="lakh": amount*=100000
                return {"amount":int(amount),"currency":"INR","raw":m.group(0)}
        return {}

    def extract_days(self,text:str)->Optional[int]:
        folded=_fold_text(text)
        for pattern in (r"\b(\d+)\s*(?:day|days|day trip)\b",r"\b(\d+)\s*(?:night|nights)\b"):
            m=re.search(pattern,folded)
            if m: return int(m.group(1))
        if _any_phrase(folded,("weekend","two days","2 day")): return 2
        return None

    def extract_party_size(self,text:str)->Optional[int]:
        folded=_fold_text(text)
        for pattern in (r"\b(\d+)\s*(?:people|persons|members|of us)\b",
                        r"\bparty of\s*(\d+)\b",r"\b(\d+)\s*adults?\b"):
            m=re.search(pattern,folded)
            if m: return int(m.group(1))
        return None

    def extract_destination(self,text:str)->Optional[str]:
        folded=_fold_text(text)
        candidates=sorted(list(DESTINATIONS)+list(DISTRICTS),key=len,reverse=True)
        for candidate in candidates:
            if _phrase_present(folded,candidate): return candidate
        return None

    def extract_origin(self,text:str)->Optional[str]:
        m=re.search(r"\bfrom\s+([A-Za-z][A-Za-z0-9 .'-]{1,45}?)(?=\s+to\s+|\s*$)",text,re.I)
        return m.group(1).strip(" .,!?") if m else None

    def flags(self,text:str)->Dict[str,bool]:
        folded=_fold_text(text)
        return {
            "is_question":"?" in text or bool(re.match(r"^(what|where|when|why|how|which|can|is|are|do|does)\b",folded)),
            "asks_current":_any_phrase(folded,("today","now","currently","latest","this week","ഇന്ന്","ഇപ്പോൾ")),
            "asks_live":_any_phrase(folded,("today","now","latest","current","live","currently","ഇന്ന്")),
            "asks_route":_any_phrase(folded,("route","distance","how far","travel time","from"," to ")),
            "asks_recommendation":_any_phrase(folded,("best","good","recommend","suggest","നല്ല","ശുപാർശ")),
            "asks_comparison":_any_phrase(folded,("compare","versus","vs","difference","better","താരതമ്യം")),
            "asks_safety":_any_phrase(folded,("safe","safety","danger","emergency","സുരക്ഷ")),
            "asks_price":_any_phrase(folded,("price","cost","budget","cheap","വില","ചെലവ്")),
            "is_followup":_any_phrase(folded,("that one","first one","second one","the place","there","it","അതൊന്ന്","അവിടെ")),
        }

    def analyze(self,text:str,legacy:Optional[Dict[str,Any]]=None)->QueryProfile:
        raw=_normalize_text(text); normalized=_fold_text(raw)
        intents=self.score_intents(raw)
        locations=[x for x in list(DESTINATIONS)+list(DISTRICTS) if _phrase_present(normalized,x)]
        actions=self.extract_actions(raw); prefs=self.extract_preferences(raw)
        entities={}
        if locations: entities["locations"]=locations
        if actions: entities["actions"]=actions
        if prefs: entities["preferences"]=prefs
        constraints={}
        budget=self.extract_budget(raw); days=self.extract_days(raw)
        party=self.extract_party_size(raw); destination=self.extract_destination(raw)
        origin=self.extract_origin(raw)
        if budget: constraints["budget"]=budget
        if days is not None: constraints["days"]=days
        if party is not None: constraints["party_size"]=party
        if destination: constraints["destination"]=destination
        if origin: constraints["origin"]=origin
        flags=self.flags(raw)
        if legacy:
            for key in ("live","research","near","length"):
                if key in legacy: flags["legacy_"+key]=bool(legacy[key])
        signals=[Signal(k,v,list(INTENT_GROUPS.get(k,()))[:4])
                 for k,v in sorted(intents.items(),key=lambda x:-x[1])[:8]]
        return QueryProfile(raw,normalized,self.detect_language(raw),intents,entities,constraints,flags,signals)

class ContextResolver:
    ORDINALS={"first":0,"1st":0,"one":0,"second":1,"2nd":1,"two":1,"third":2,"3rd":2,
              "three":2,"fourth":3,"4th":3,"four":3,"fifth":4,"5th":4,"five":4}
    def resolve(self,profile:QueryProfile,context:Dict[str,Any],state:Dict[str,Any])->Dict[str,Any]:
        resolved=dict(context or {})
        state=dict(state or {})
        previous=resolved.get("last_results") or state.get("last_results") or []
        if profile.flags.get("is_followup") and previous:
            for word,index in self.ORDINALS.items():
                if _phrase_present(profile.normalized,word) and index < len(previous):
                    item=previous[index]
                    if isinstance(item,dict):
                        name=item.get("name") or item.get("title")
                        if name:
                            resolved["current_place_name"]=name
                            resolved["resolved_reference"]=name
                    break
        if not resolved.get("current_place_name") and profile.entities.get("locations"):
            resolved["current_place_name"]=profile.entities["locations"][0]
        if profile.constraints.get("destination") and not resolved.get("destination"):
            resolved["destination"]=profile.constraints["destination"]
        if profile.constraints.get("origin") and not resolved.get("origin"):
            resolved["origin"]=profile.constraints["origin"]
        resolved["language"]=resolved.get("language") or profile.language
        return resolved

class IntentArbiter:
    PRIORITY=("research","travel","services","food","places","knowledge","education")
    def choose(self,profile:QueryProfile,mode:str,legacy:Dict[str,Any])->Dict[str,Any]:
        scores=defaultdict(float)
        for intent,score in profile.intents.items(): scores[intent]+=score
        if profile.flags.get("asks_live"): scores["research"]+=.45
        if profile.flags.get("asks_route"): scores["travel"]+=.55
        if profile.flags.get("asks_price"): scores["shopping"]+=.15
        if profile.flags.get("asks_recommendation"): scores["places"]+=.20
        if mode=="research": scores["research"]+=1.0
        if mode=="travel": scores["travel"]+=.8
        if mode=="local": scores["services"]+=.8
        if mode=="study": scores["education"]+=.8
        if legacy.get("near"): scores["services"]+=.5
        if legacy.get("live"): scores["research"]+=.5
        ranked=sorted(scores.items(),key=lambda x:(-x[1],self.PRIORITY.index(x[0]) if x[0] in self.PRIORITY else 99))
        return {"primary":ranked[0][0] if ranked else "general",
                "ranked":[{"intent":k,"score":round(v,4)} for k,v in ranked[:8]]}

class DeterministicPlanner:
    def build(self,message,mode,profile,context,arbiter):
        primary=arbiter.get("primary","general"); flags=profile.flags; steps=[]
        if primary=="research" or mode=="research":
            steps.append(PlanStep("live",10,"Current or research-oriented query."))
        if primary in {"places","food"}:
            steps.append(PlanStep("places",20,"Retrieve private place data."))
        if primary in {"knowledge","education"} or mode=="study":
            steps.append(PlanStep("knowledge",20,"Retrieve structured Kerala knowledge."))
        if primary=="services" or mode=="local":
            steps.append(PlanStep("services",20,"Retrieve nearby practical services."))
        if flags.get("asks_route") or mode=="travel":
            steps.append(PlanStep("travel",30,"Calculate route information.",True))
        if flags.get("asks_live") and not any(s.name=="live" for s in steps):
            steps.append(PlanStep("live",40,"Verify current information.",True))
        if flags.get("asks_comparison") and not any(s.name=="places" for s in steps):
            steps.append(PlanStep("places",25,"Retrieve comparison candidates.",True))
        if not steps and mode in {"normal","explore"} and len(profile.normalized)>=3:
            steps.append(PlanStep("places",80,"Cheap fallback grounding pass.",True))
        unique={}
        for step in steps:
            if step.name not in unique or step.priority < unique[step.name].priority:
                unique[step.name]=step
        return sorted(unique.values(),key=lambda x:x.priority)

class RetrievalNormalizer:
    def items(self,result:Any)->List[Dict[str,Any]]:
        if not isinstance(result,dict): return []
        for key in ("places","results","knowledge","items","services"):
            value=result.get(key)
            if isinstance(value,list): return [x for x in value if isinstance(x,dict)]
        nested=result.get("data")
        if isinstance(nested,dict):
            for key in ("places","results","knowledge","items","services"):
                value=nested.get(key)
                if isinstance(value,list): return [x for x in value if isinstance(x,dict)]
        return []
    def normalize_place(self,item):
        return {**item,
                "name":str(item.get("name") or item.get("title") or "Unknown place"),
                "description":str(item.get("shortDescription") or item.get("description") or item.get("content") or ""),
                "district":str(item.get("district") or item.get("location") or ""),
                "imageUrl":item.get("imageUrl") or item.get("image_url") or item.get("image") or ""}
    def place_items(self,result): return [self.normalize_place(x) for x in self.items(result)]

class CandidateRanker:
    def _text(self,item):
        return _fold_text(" ".join(str(item.get(k,"")) for k in
                                   ("name","title","description","shortDescription","district","category","tags","type")))
    def score(self,item,profile,context):
        text=self._text(item)
        q=set(_tokens(profile.raw)); c=set(_tokens(text))
        lexical=min(len(q&c)/max(len(q),1),1.0)
        destination=profile.constraints.get("destination") or context.get("destination")
        location=0.0
        if destination:
            d=_fold_text(destination)
            location=1.0 if d in text else (.45 if any(t in text for t in _tokens(d)) else 0.0)
        preference=.0
        for p in profile.entities.get("preferences",[]):
            if p in text: preference+=.12
        image=.05 if item.get("imageUrl") else 0
        desc=min(len(str(item.get("description","")))/500,.12)
        rating=item.get("rating") or item.get("score") or 0
        try: rating_score=min(float(rating)/5,1)*.10
        except: rating_score=0
        return round(lexical*.40+location*.25+preference+image+desc+rating_score,5)
    def rank(self,items,profile,context,limit=8):
        scored=[]
        for item in items:
            x=dict(item); x["_octapus_score"]=self.score(x,profile,context); scored.append(x)
        return sorted(scored,key=lambda x:x.get("_octapus_score",0),reverse=True)[:limit]
    def diversify(self,items,limit=8):
        out=[]; seen=set()
        for item in items:
            key=(_fold_text(item.get("district","")),_fold_text(item.get("category","")),_fold_text(item.get("name","")))
            if key in seen: continue
            seen.add(key); out.append(item)
            if len(out)>=limit: break
        return out

class EvidenceGate:
    def classify(self,result,live=False):
        items=result if isinstance(result,list) else []
        if not items: return {"level":"none","count":0,"reliable":False}
        return {"level":"live" if live else "grounded","count":len(items),"reliable":True}
    def should_disclose_uncertainty(self,data,profile):
        if profile.flags.get("asks_live") and not data.get("live"): return True
        if profile.flags.get("asks_safety") and not data.get("services"): return True
        if profile.flags.get("asks_price") and not data.get("live") and not data.get("places"): return True
        return False

class ResponseComposer:
    def __init__(self,rng=None): self.rng=rng or random.Random()
    def greeting(self):
        return ("Namaskaram 🙏 I’m ready. Give me a place, question, plan, challenge, "
                "or switch to **fun**, **quiz**, **study**, **travel**, **explore**, **local**, or **research**.")
    def places(self,items,profile):
        if not items: return "I couldn't find a strong place match in the grounded data yet."
        lines=[f"I found **{len(items)}** relevant place(s):"]
        for item in items[:6]:
            name=item.get("name") or item.get("title") or "Place"
            desc=str(item.get("description") or "").strip()
            if len(desc)>180: desc=desc[:177]+"..."
            district=item.get("district"); suffix=f" — {desc}" if desc else ""
            if district and district.lower() not in desc.lower(): suffix+=f" · {district}"
            lines.append(f"• **{name}**{suffix}")
        return "\n".join(lines)
    def knowledge(self,items):
        if not items: return "I couldn't find a grounded knowledge record for that topic."
        item=items[0]; title=item.get("title") or item.get("name") or "Topic"
        return f"**{title}**\n\n{item.get('description') or item.get('content') or ''}".strip()
    def live(self,result):
        results=result.get("results",[]) if isinstance(result,dict) else []
        if not results: return "I couldn't collect enough current sources to answer that confidently."
        lines=["**Current information**"]
        for i,item in enumerate(results[:4],1):
            title=item.get("title") or "Source"; content=str(item.get("content") or "").strip().replace("\n"," ")
            if len(content)>260: content=content[:257]+"..."
            lines.append(f"{i}. **{title}** — {content}")
            if item.get("url"): lines.append(f"   Source: {item['url']}")
        return "\n".join(lines)
    def travel(self,data,profile):
        info=(data.get("travel",{}).get("travelInfo") if isinstance(data.get("travel"),dict) else None)
        lines=["🧭 **Travel plan**"]
        if info: lines.append(f"**Route:** {info.get('distanceText') or info.get('distance') or 'distance unavailable'} • {info.get('durationText') or info.get('duration') or 'time unavailable'}")
        if profile.constraints.get("destination"): lines.append(f"**Destination:** {profile.constraints['destination']}")
        if profile.constraints.get("days"): lines.append(f"**Duration:** {profile.constraints['days']} days")
        if profile.constraints.get("budget"): lines.append(f"**Budget signal:** about ₹{profile.constraints['budget']['amount']:,}")
        if not info: lines.append("I have not received route data yet; I can still build a destination plan from grounded place data.")
        return "\n".join(lines)
    def services(self,result):
        items=result.get("results") or result.get("services") or result.get("items") or []
        if not items: return "I couldn't find a matching nearby service."
        lines=["📍 **Nearby options**"]
        for item in items[:7]:
            if isinstance(item,dict):
                lines.append(f"• **{item.get('name') or item.get('title') or 'Service'}**" +
                             (f" · {item.get('distance') or item.get('distanceText')}" if item.get('distance') or item.get('distanceText') else ""))
        return "\n".join(lines)

class StateManager:
    def update(self,state,mode,profile,items):
        out=dict(state or {})
        out.update({"mode":mode,"language":profile.language,
                    "last_intent":max(profile.intents,key=profile.intents.get) if profile.intents else "general",
                    "last_query":profile.raw,
                    "last_results":[dict(x) for x in items[:8]],
                    "constraints":dict(profile.constraints)})
        if profile.constraints.get("destination"): out["destination"]=profile.constraints["destination"]
        if profile.constraints.get("origin"): out["origin"]=profile.constraints["origin"]
        return out
