def classify_expanded_phrases(text:str)->Dict[str,float]:
    folded=_fold_text(text); scores=defaultdict(float)
    for category,phrase in EXPANDED_ROUTING_RULES:
        if _phrase_present(folded,phrase):
            scores[category]+=1.0+min(len(phrase)/40.0,1.0)
    total=sum(scores.values()) or 1.0
    return {k:round(v/total,4) for k,v in scores.items()}

