def matrix_match(text:str,limit:int=12)->List[Dict[str,str]]:
    folded=_fold_text(text); out=[]
    for action,domain,audience,constraint in MATRIX_RULES:
        if (_phrase_present(folded,action) and _phrase_present(folded,domain)
            and _phrase_present(folded,audience) and _phrase_present(folded,constraint)):
            out.append({"action":action,"domain":domain,"audience":audience,"constraint":constraint})
            if len(out)>=limit: break
    return out

def estimate_answer_complexity(profile:QueryProfile)->Dict[str,Any]:
    score=1+max(0,len(profile.intents)-1)+len(profile.constraints)+len(profile.entities)
    if profile.flags.get("asks_comparison"): score+=2
    if profile.flags.get("asks_current"): score+=2
    if profile.flags.get("is_followup"): score+=1
    return {"score":score,"level":"low" if score<=2 else "medium" if score<=5 else "high"}

def analyze_query(message:str,history=None,context=None)->Dict[str,Any]:
    analyzer=QueryAnalyzer()
    legacy={}
    try: legacy=parse_query(message,history or [],(context or {}).get("location"))
    except Exception: legacy={}
    profile=analyzer.analyze(message,legacy)
    return {"language":profile.language,"intents":profile.intents,"entities":profile.entities,
            "constraints":profile.constraints,"flags":profile.flags,
            "expanded_intents":classify_expanded_phrases(message),
            "complexity":estimate_answer_complexity(profile)}

def _quality_snapshot(self,message,data):
    profile=self.analyzer.analyze(message,{})
    return {"complexity":estimate_answer_complexity(profile),
            "expanded_intents":classify_expanded_phrases(message),
            "matrix_matches":matrix_match(message),
            "grounded":bool(data.get("places") or data.get("knowledge") or data.get("live") or data.get("services")),
            "has_current_evidence":bool(data.get("live"))}

OctapusV5Engine.quality_snapshot=_quality_snapshot

REGRESSION_QUERIES = (
    "hi","hello Octapus","മുന്നാറിൽ 2 ദിവസത്തേക്ക് പോകാൻ നല്ല സ്ഥലങ്ങൾ?",
    "best vegetarian restaurant in Kochi","how far is Munnar from Kochi",
    "find a hospital near me","research the latest Munnar weather",
    "compare Munnar and Vagamon","teach me about Kerala history",
    "quiz me about Kerala","tell me a story about Wayanad",
    "budget trip to Alleppey for family","quiet places in Wayanad for a couple",
    "what can I do today in Varkala","find cheap food near me",
    "what is the route from Kochi to Munnar","show me places with waterfalls",
    "give me sources for this information","എറണാകുളത്ത് നല്ല ഭക്ഷണം എവിടെ കിട്ടും",
    "വയനാട്ടിൽ കുടുംബമായി പോകാൻ നല്ല സ്ഥലം","ഇന്ന് കൊച്ചിയിൽ എന്ത് ചെയ്യാം",
    "മുന്നാറിൽ നിന്ന് തേക്കടിയിലേക്ക് എങ്ങനെ പോകാം","എന്നെ കേരളത്തെക്കുറിച്ച് quiz ചെയ്യൂ",
)

def run_regression_probes(engine:OctapusV5Engine)->List[Dict[str,Any]]:
    out=[]
    for query in REGRESSION_QUERIES:
        try:
            a=engine.analyze(query)
            out.append({"query":query,"ok":True,"language":a["language"],
                        "intents":a["intents"],"constraints":a["constraints"]})
        except Exception as exc:
            out.append({"query":query,"ok":False,"error":str(exc)})
    return out

ENGINE_FEATURES = (
    "query_normalization","language_detection","intent_scoring","entity_extraction",
    "budget_extraction","duration_extraction","party_size_extraction",
    "destination_resolution","followup_resolution","deterministic_planning",
    "tool_orchestration","place_reranking","candidate_diversification",
    "evidence_gating","current_information_routing","comparison_handling",
    "quiz_state","voice_preparation","observability","regression_probes",
)

def engine_info():
    return {"name":"OctapusV5Engine","version":OctapusV5Engine.VERSION,
            "features":list(ENGINE_FEATURES),
            "matrix_rules":len(MATRIX_RULES),
            "expanded_routing_rules":len(EXPANDED_ROUTING_RULES)}

class OctapusV5Engine:
    """Expanded deterministic orchestration layer. LLMs are optional."""

    VERSION = "5.2.0-intelligence"

    def __init__(self, tools: Dict[str, Tool], web_research=None):
        self.tools=tools
        self.web=web_research
        self.voice=VoiceEngine()
        self.rng=random.Random()
        self.analyzer=QueryAnalyzer()
        self.context_resolver=ContextResolver()
        self.arbiter=IntentArbiter()
        self.planner=DeterministicPlanner()
        self.normalizer=RetrievalNormalizer()
        self.ranker=CandidateRanker()
        self.evidence_gate=EvidenceGate()
        self.composer=ResponseComposer(self.rng)
        self.state_manager=StateManager()

    def _call(self,name:str,**kwargs)->Dict[str,Any]:
        fn=self.tools.get(name)
        if not fn: return {"ok":False,"error":"tool_unavailable","tool":name}
        started=time.perf_counter()
        try:
            result=fn(kwargs)
            if not isinstance(result,dict): result={"ok":True,"data":result}
            result.setdefault("ok",True)
            result["latency_ms"]=round((time.perf_counter()-started)*1000,1)
            return result
        except Exception as exc:
            return {"ok":False,"error":str(exc),"tool":name,
                    "latency_ms":round((time.perf_counter()-started)*1000,1)}

    def _legacy_parse(self,message,history,location):
        try:
            x=parse_query(message,history or [],location)
            return x if isinstance(x,dict) else {}
        except Exception:
            return {}

    def plan(self,message,mode,parsed):
        profile=self.analyzer.analyze(message,parsed)
        arbiter=self.arbiter.choose(profile,mode,parsed)
        return [x.name for x in self.planner.build(message,mode,profile,{},arbiter)]

    def _knowledge_category(self,profile,context):
        if context.get("knowledge_category"): return str(context["knowledge_category"])
        q=profile.normalized
        if "education" in q or "study" in q: return "education"
        if "history" in q: return "history"
        if "culture" in q: return "culture"
        if "festival" in q: return "festival"
        if "writer" in q or "author" in q: return "writer"
        if "book" in q: return "book"
        if "government" in q: return "government_service"
        if "food" in q: return "food_knowledge"
        return "general_kerala"

    def _service_category(self,profile,context):
        if context.get("service_category"): return str(context["service_category"])
        q=profile.normalized
        if _any_phrase(q,("hospital","clinic","doctor","pharmacy")): return "osm_health"
        if _any_phrase(q,("atm","bank","money")): return "osm_money"
        if _any_phrase(q,("petrol","fuel","gas station")): return "osm_fuel"
        if _any_phrase(q,("bus","train","station","airport","taxi")): return "osm_transport"
        if _any_phrase(q,("police","fire","emergency")): return "osm_emergency"
        if _any_phrase(q,("hotel","stay","resort","homestay")): return "osm_stay"
        return "food"

    def retrieve(self,message,mode,parsed,context):
        profile=self.analyzer.analyze(message,parsed)
        resolved=self.context_resolver.resolve(profile,context,context.get("state",{}))
        arbiter=self.arbiter.choose(profile,mode,parsed)
        steps=self.planner.build(message,mode,profile,resolved,arbiter)
        data={}; evidence=[]; latencies=[]
        location=resolved.get("location") if isinstance(resolved.get("location"),dict) else {}
        for step in steps:
            if step.name=="places":
                query=resolved.get("resolved_reference") or profile.constraints.get("destination") or message
                result=self._call("search_places",query=query,limit=10)
                items=self.normalizer.place_items(result)
                items=self.ranker.rank(items,profile,resolved,10)
                items=self.ranker.diversify(items,8)
                result["results"]=items; result["places"]=items
                data["places"]=result
            elif step.name=="knowledge":
                data["knowledge"]=self._call("search_knowledge",query=message,
                    category=self._knowledge_category(profile,resolved),limit=8)
            elif step.name=="services":
                data["services"]=self._call("search_services",query=message,
                    category=self._service_category(profile,resolved),limit=10,
                    lat=location.get("lat",0),lng=location.get("lng",0))
            elif step.name=="travel":
                origin=profile.constraints.get("origin") or resolved.get("origin") or location.get("text") or "current location"
                destination=profile.constraints.get("destination") or resolved.get("destination") or resolved.get("current_place_name")
                if destination:
                    data["travel"]=self._call("travel_info",origin=origin,destination=destination)
                else:
                    data["travel"]={"ok":False,"error":"destination_not_specified","travelInfo":None}
            elif step.name=="live":
                if self.web:
                    try:
                        result=self.web.research(message,limit=6,deep=(mode=="research" or profile.flags.get("asks_live",False)))
                    except Exception as exc:
                        result={"ok":False,"error":str(exc),"results":[]}
                else:
                    result=self._call("live_search",query=message,limit=6)
                data["live"]=result
                if isinstance(result,dict) and isinstance(result.get("results"),list):
                    evidence.extend(result["results"])
            for value in data.values():
                if isinstance(value,dict) and value.get("latency_ms") is not None:
                    latencies.append(float(value["latency_ms"]))
        data["plan"]=[x.name for x in steps]
        data["plan_detail"]=[x.__dict__ for x in steps]
        data["arbiter"]=arbiter
        data["query_profile"]={"language":profile.language,"intents":profile.intents,
                               "entities":profile.entities,"constraints":profile.constraints,
                               "flags":profile.flags}
        data["resolved_context"]=resolved
        data["latency_ms"]=round(sum(latencies),1)
        data["evidence_gate"]=self.evidence_gate.classify(evidence,live=bool(data.get("live")))
        return data

    def _first_items(self,result,keys=("places","results","knowledge")):
        return self.normalizer.items(result)

    def _quiz(self,message,data,state):
        score=int(state.get("score",0) or 0); qnum=int(state.get("question",0) or 0)
        expected=str(state.get("expected","")).strip().lower()
        answer_text=_fold_text(message); feedback=""
        if expected and answer_text and answer_text!="hint":
            if expected in answer_text or answer_text in expected:
                score+=1; feedback="✅ Correct!"
            else: feedback=f"❌ Not quite. The answer was **{state.get('expected')}**."
        items=self._first_items(data.get("knowledge",{}))
        if items:
            item=items[0]; topic=item.get("title") or item.get("name") or "Kerala"
            expected_value=item.get("name") or item.get("title") or topic
            question=f"Quick challenge: what can you tell me about **{topic}**?"
        else:
            question="Quick challenge: Which state is known as God's Own Country?"
            expected_value="Kerala"
        qnum+=1
        next_state={**state,"score":score,"question":qnum,"expected":expected_value,"mode":"quiz"}
        if answer_text=="hint": question="💡 Hint: the answer is connected to **Kerala**.\n\n"+question
        return f"{feedback+' ' if feedback else ''}🏆 **Score: {score}** • Question {qnum}\n\n{question}\n\nReply with your answer — or say **hint**.",next_state

    def _fun(self,message,data,state):
        places=self.normalizer.place_items(data.get("places",{}))
        topic=places[0].get("name") if places else "Kerala"
        return self.rng.choice([
            f"🎮 **Fun mode:** Your mission is to discover one surprising thing about **{topic}** and tell me whether you'd try it.",
            f"😈 **Challenge accepted.** I found **{topic}**. Choose: **explore it**, **quiz yourself**, or **turn it into a mini adventure**.",
            f"🔥 **Boredom detected.** Today's target is **{topic}**. Pick: **A) challenge B) riddle C) adventure**.",
        ])

    def build_response(self,message,mode,parsed,data,context,state):
        profile=self.analyzer.analyze(message,parsed)
        if mode=="quiz": return self._quiz(message,data,state)
        if mode=="fun": return self._fun(message,data,state),state
        if mode=="story":
            places=self.normalizer.place_items(data.get("places",{}))
            name=places[0].get("name") if places else context.get("current_place_name","Kerala")
            return (f"🌴 **Story mode**\n\nYou arrive in **{name}** just before sunset. "
                    "The road ahead splits in two: one path leads toward a quiet view, "
                    "the other toward lights, music, and something that definitely wasn't "
                    "on the map.\n\n**Choose:** `quiet` or `mystery`.",state)
        if mode=="research": return self.composer.live(data.get("live",{})),state
        if mode=="travel": return self.composer.travel(data,profile),state
        if mode in ("explore","local"):
            if data.get("services"): return self.composer.services(data["services"]),state
            return self.composer.places(self.normalizer.place_items(data.get("places",{})),profile),state
        if profile.normalized in {"hi","hello","hey","hey octapus","namaskaram","good morning","good evening"}:
            return self.composer.greeting(),state
        places=self.normalizer.place_items(data.get("places",{}))
        knowledge=self.normalizer.items(data.get("knowledge",{}))
        live=data.get("live",{})
        if mode=="study" and knowledge:
            item=knowledge[0]
            return (f"📚 **Learn it simply**\n\n**{item.get('title') or item.get('name') or 'Topic'}**\n\n"
                    f"{item.get('description') or item.get('content') or ''}\n\n"
                    "**Practice:** Tell me the idea back in one sentence and I’ll check it.",state)
        if profile.flags.get("asks_comparison") and len(places)>=2:
            a,b=places[:2]
            return (f"**Comparison**\n\n• **{a.get('name','Option A')}** — {a.get('description','')[:220]}\n"
                    f"• **{b.get('name','Option B')}** — {b.get('description','')[:220]}\n\n"
                    "The better fit depends on your goal, budget, time and preferences.",state)
        if places: return self.composer.places(places,profile),state
        if knowledge: return self.composer.knowledge(knowledge),state
        if isinstance(live,dict) and live.get("results"): return self.composer.live(live),state
        if self.evidence_gate.should_disclose_uncertainty(data,profile):
            return ("I need a stronger current source or grounded record before I state that as a fact. "
                    "Try giving me the exact place, date, or topic and I’ll route it to the appropriate source.",state)
        return ("I don't have enough grounded information to answer that confidently yet. "
                "Try giving me a place, topic, time, or goal and I'll route it to the right capability.",state)

    def run(self,message,*,mode="",history=None,context=None,state=None,voice=False,voice_locale=""):
        started=time.perf_counter()
        context=dict(context or {}); state=dict(state or {}); history=history or []
        current_mode=state.get("mode") or context.get("mode") or "normal"
        try: current_mode=normalize_mode(current_mode)
        except Exception: current_mode="normal"
        selected_mode=detect_mode(message,mode,current_mode)
        legacy=self._legacy_parse(message,history,context.get("location"))
        profile=self.analyzer.analyze(message,legacy)
        resolved=self.context_resolver.resolve(profile,context,state)
        resolved["state"]=state
        data=self.retrieve(message,selected_mode,legacy,resolved)
        reply,new_state=self.build_response(message,selected_mode,legacy,data,resolved,state)
        items=self.normalizer.place_items(data.get("places",{}))
        new_state=self.state_manager.update(new_state,selected_mode,profile,items)
        evidence=data.get("live",{}).get("results",[]) if isinstance(data.get("live"),dict) else []
        return {
            "version":self.VERSION,"mode":selected_mode,"reply":reply,"state":new_state,
            "parser":{**legacy,"intelligence":{"language":profile.language,"intents":profile.intents,
                "entities":profile.entities,"constraints":profile.constraints,"flags":profile.flags}},
            "plan":data.get("plan",[]),"planDetail":data.get("plan_detail",[]),
            "evidence":evidence,"data":data,"aiUsed":False,"llmCalls":0,
            "voice":self.voice.prepare(reply,voice_locale) if voice else None,
            "metrics":{"latency_ms":round((time.perf_counter()-started)*1000,1),
                       "tool_latency_ms":data.get("latency_ms",0),
                       "planner_steps":len(data.get("plan",[])),
                       "grounded_items":len(items),"evidence_items":len(evidence)}
        }

    def analyze(self,message,history=None,context=None):
        legacy=self._legacy_parse(message,history or [],(context or {}).get("location"))
        profile=self.analyzer.analyze(message,legacy)
        return {"version":self.VERSION,"legacy":legacy,"language":profile.language,
                "intents":profile.intents,"entities":profile.entities,
                "constraints":profile.constraints,"flags":profile.flags,
                "signals":[{"name":s.name,"score":s.score,"evidence":s.evidence} for s in profile.signals]}

    def intelligence_plan(self,message,mode="",history=None,context=None):
        context=dict(context or {})
        legacy=self._legacy_parse(message,history or [],context.get("location"))
        profile=self.analyzer.analyze(message,legacy)
        selected=detect_mode(message,mode,context.get("mode","normal"))
        resolved=self.context_resolver.resolve(profile,context,context.get("state",{}))
        arbiter=self.arbiter.choose(profile,selected,legacy)
        steps=self.planner.build(message,selected,profile,resolved,arbiter)
        return {"version":self.VERSION,"mode":selected,"arbiter":arbiter,
                "steps":[x.__dict__ for x in steps],"resolved":resolved}

    def health(self):
        return {"ok":True,"engine":"OctapusV5Engine","version":self.VERSION,
                "tool_count":len(self.tools),"tools":sorted(self.tools.keys()),
                "web_research":bool(self.web),"deterministic":True}

